const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Bhadla Solar Park, Rajasthan, India approximate coordinates.
  // This is a broad bounding box covering the main sections of the park.
  const geometry = ee.Geometry.Polygon(
    [[[71.80210777596001, 27.53039783701267],
      [71.80210777596001, 27.340078716503716],
      [72.07185078047661, 27.340078716503716],
      [72.07185078047661, 27.53039783701267]]], null, false);

  const startDate = '2022-01-01';
  const endDate = '2022-01-31';
  const scale = 10; // Sentinel-2 native resolution is 10m for visible/NIR bands

  // 2. Data Acquisition & Check
  let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(geometry)
    .filterDate(startDate, endDate)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20)); // Filter by cloud percentage

  // Check if collection is empty
  let collectionSize = await collection.size().getInfo();
  if (collectionSize === 0) {
    console.log("No Sentinel-2 images found for January 2022 after cloud filtering.");
    console.log("C1");
    return;
  }

  // Cloud masking function for Sentinel-2 SR
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    // Bits 10 and 11 are clouds and cirrus, respectively.
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).divide(10000); // Scale reflectance to 0-1
  }

  let maskedCollection = collection.map(maskS2clouds);

  // Take the median composite to get a representative image
  let image = maskedCollection.median();

  // Check for valid pixels after masking
  // Using B4 (Red) as a proxy for valid pixels.
  let bandNames = await image.bandNames().getInfo();
  if (!bandNames || !bandNames.includes('B4')) {
    console.log("Image has no B4 band, indicating potential issue with collection or masking.");
    console.log("C3");
    return;
  }

  // 3. Processing: Identify solar panels
  // Solar panels are characterized by very low reflectance, especially in NIR and SWIR.
  // Using a heuristic approach: very low NIR (B8), SWIR1 (B11), and Blue (B2) reflectance.
  // These thresholds are empirical and might need tuning for different regions/sensors.
  // Values are based on scaled reflectance (0-1).
  const solarPanelMask = image.select('B8').lt(0.08) // Very low NIR reflectance
    .and(image.select('B11').lt(0.1)) // Low SWIR1 reflectance
    .and(image.select('B2').lt(0.12)) // Low Blue reflectance
    .and(image.select('B4').lt(0.12)); // Low Red reflectance

  // Calculate the number of solar panel pixels
  const solarPanelPixels = solarPanelMask.rename('solar_panels');

  let pixelCountResult = await solarPanelPixels.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('solar_panels').getInfo();

  if (pixelCountResult === null || isNaN(pixelCountResult)) {
    console.log("Calculation of pixel count failed.");
    console.log("C3");
    return;
  }

  const validSolarPanelPixels = pixelCountResult;

  if (validSolarPanelPixels === 0) {
    console.log("No valid solar panel pixels identified after masking and thresholding.");
    console.log("C2");
    return;
  }

  // 4. Calculation: Area calculation
  const pixelAreaSqM = scale * scale; // Area of one pixel in square meters
  const totalSolarPanelAreaSqM = validSolarPanelPixels * pixelAreaSqM;
  const totalSolarPanelAreaHectares = totalSolarPanelAreaSqM / 10000; // 1 hectare = 10,000 sq meters

  // 5. Validation & Final Answer
  const thresholdHectares = 7000;
  const isGreaterThanThreshold = totalSolarPanelAreaHectares > thresholdHectares;

  console.log(`Images in collection: ${collectionSize}`);
  console.log(`Solar panel area (hectares): ${totalSolarPanelAreaHectares.toFixed(2)}`);
  console.log(`Valid solar panel pixels: ${validSolarPanelPixels}`);

  if (isGreaterThanThreshold) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
